<style>
:root{--bg:#07151B;--panel:#0f1f2c;--panel2:#13283a;--line:#1f3a4f;--ink:#EAF4F2;--mut:#9DB2B2;--teal:#2DD4BF;--teal2:#14B8A6;--gold:#E7B53C;--gold2:#F2C75B;--red:#e5484d;--amber:#E7B53C;--green:#30a46c}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 -apple-system,Segoe UI,Roboto,Arial,sans-serif}
a{color:var(--teal)}
button{font:inherit;cursor:pointer;border:0;border-radius:8px;padding:8px 14px;background:var(--panel2);color:var(--ink);border:1px solid var(--line)}
button:hover{border-color:var(--teal)}
button.primary{background:var(--teal2);border-color:var(--teal2);color:#fff;font-weight:600}
button.sm{padding:5px 10px;font-size:12.5px}
input{font:inherit;background:#0a141d;color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px}
input:focus{outline:none;border-color:var(--teal)}
#login{max-width:360px;margin:12vh auto;padding:28px;background:var(--panel);border:1px solid var(--line);border-radius:16px}
#login h1{font-size:20px;margin:0 0 4px}
#login p{color:var(--mut);margin:0 0 18px;font-size:13px}
#login input{width:100%;margin-bottom:10px}
#login button{width:100%}
.err{color:#ffb4b6;font-size:13px;min-height:18px;margin-top:6px}
header.top{display:flex;align-items:center;gap:12px;padding:10px 16px;background:var(--panel);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:20;flex-wrap:wrap}
header.top img{height:22px}
header.top .brand{font-weight:800;letter-spacing:.5px}
header.top .brand .os{color:var(--gold)}
.tag{font-size:11px;color:var(--mut);border:1px solid var(--line);border-radius:999px;padding:2px 9px}
.spacer{flex:1}
.who{color:var(--mut);font-size:12px}
.wrap{padding:18px 20px;max-width:1280px;margin:0 auto}
.asof{color:var(--mut);font-size:12px;margin:0 0 14px}
.hero{display:grid;grid-template-columns:220px 1fr;gap:18px;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:18px}
@media(max-width:720px){.hero{grid-template-columns:1fr}}
.gauge{text-align:center}
.gauge .num{font-size:56px;font-weight:800;line-height:1}
.gauge .lbl{font-size:11px;text-transform:uppercase;letter-spacing:.6px;color:var(--mut);margin-top:6px}
.band{display:inline-block;margin-top:8px;padding:3px 12px;border-radius:999px;font-size:12px;font-weight:700;text-transform:capitalize}
.band.excellent,.band.good{background:#0c2b20;color:#5be0a8;border:1px solid #17533c}
.band.attention{background:#2e2410;color:#f5c451;border:1px solid #5b461a}
.band.critical{background:#3a1416;color:#ff9a9c;border:1px solid #5b1f22}
.comps{display:grid;grid-template-columns:1fr 1fr;gap:10px 20px;align-self:center}
@media(max-width:520px){.comps{grid-template-columns:1fr}}
.comp .r{display:flex;justify-content:space-between;font-size:12.5px;margin-bottom:3px}
.comp .r .k{color:var(--mut)}
.comp .bar{height:7px;background:#0a141d;border:1px solid var(--line);border-radius:999px;overflow:hidden}
.comp .bar i{display:block;height:100%;background:linear-gradient(90deg,var(--teal2),var(--teal));border-radius:999px}
.comp.na .bar i{background:#33475a}
.comp.na .r .v{color:var(--mut)}
.sec{margin:18px 0 10px;font-size:12px;text-transform:uppercase;letter-spacing:.5px;color:var(--mut)}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px}
.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px 15px}
.card .k{font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:var(--mut)}
.card .v{font-size:26px;font-weight:800;margin-top:4px}
.card .s{font-size:11.5px;color:var(--mut);margin-top:2px}
.card.gold .v{color:var(--gold2)}
.card.warn{border-color:#5b461a}
.card.warn .v{color:#f5c451}
.card.bad{border-color:#5b1f22}
.card.bad .v{color:#ff9a9c}
.card.good .v{color:#5be0a8}
table{width:100%;border-collapse:collapse;background:var(--panel);border:1px solid var(--line);border-radius:12px;overflow:hidden;margin-top:6px}
th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);font-size:13px;vertical-align:middle}
th{color:var(--mut);font-weight:600;font-size:11px;text-transform:uppercase;letter-spacing:.4px}
tbody tr:last-child td{border-bottom:0}
tbody tr:hover{background:var(--panel2)}
.pill{display:inline-block;padding:2px 9px;border-radius:999px;font-size:11.5px;font-weight:600;border:1px solid var(--line)}
.pill.blocked,.pill.held_for_review{background:#3a1416;color:#ff9a9c;border-color:#5b1f22}
.pill.escalate{background:#2e2410;color:#f5c451;border-color:#5b461a}
.pill.auto_approve,.pill.approve{background:#0c2b20;color:#5be0a8;border-color:#17533c}
.pill.muted{background:#10212e;color:var(--mut)}
.empty{padding:34px;text-align:center;color:var(--mut)}
#toast{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);background:var(--panel2);border:1px solid var(--teal);color:#fff;padding:9px 16px;border-radius:10px;display:none;z-index:60;box-shadow:0 8px 30px rgba(0,0,0,.4)}
.dim{color:var(--mut)}
</style>
